INSERT INTO ai_messages (id, conversation_id, role, content, created_at) VALUES (100, 16, 'assistant', 'أهلاً! أنا خالد، مستشار الاستثمار في Kinglike Luxury. سعيد بوجودك معنا. ما هو هدفك الرئيسي من شراء العقار؟ هل تفكر في الاستثمار، أم السكن الشخصي، أو ربما شيء آخر؟', '2026-05-28T14:50:43.582Z');
