INSERT INTO properties (id, title, description, price, location, area, bedrooms, bathrooms, property_type, images, features, status, owner_id, created_at, updated_at, listing_type, listing_expires_at, videos, floor_number, amenities, location_score, value_score, amenities_score, condition_score, investment_score, overall_score, latitude, longitude, top_rated, ready_status, is_sold, price_max, land_type, land_features, payment_method, down_payment_percent, installment_duration, best_price, title_en, description_en, acceptable_price, high_price, live_enabled, live_title, live_embed_url, live_source_type, live_status, live_thumbnail, live_country, live_city, live_updated_at, monthly_installment, remaining_balance, payment_notes) VALUES (4, 'Lamborghini Tower Batumi ', 'Batumi island is an unique project that simultaneously expands the opportunities and territorial boundaries of the Adjara region. As the first artificial island in the Black Sea, it will redefine the coastline of Batumi and present to the world a premier address for living, recreation and investment. Spread over 84 hectares, two artificial peninsulas and an island will introduce ultra-modern infrastructure, luxurious resorts and unparalleled lifestyle opportunities. The project is designed for those who are passionate about innovation and exceptional perspectives, where modern architecture and sustainable development harmonize and where business, culture and sports find their ideal environment."', 185000, 'Batumi, Georgia', '35,100', 1, 1, 'project', '["https://res.cloudinary.com/dmfy0mz7g/image/upload/v1778454706/kinglike/photos/migrated_7c1879c6-f5ce-457a-8bb8-ed4ed968026e.jpg","https://res.cloudinary.com/dmfy0mz7g/image/upload/v1778454707/kinglike/photos/migrated_9f597d03-6267-41a1-ad72-a55ea8879435.jpg","https://res.cloudinary.com/dmfy0mz7g/image/upload/v1778454707/kinglike/photos/migrated_fa02b590-594a-4961-967c-60fefdac18fa.jpg","https://res.cloudinary.com/dmfy0mz7g/image/upload/v1778454708/kinglik