INSERT INTO properties (id, title, description, price, location, area, bedrooms, bathrooms, property_type, images, features, status, owner_id, created_at, updated_at, listing_type, listing_expires_at, videos, floor_number, amenities, location_score, value_score, amenities_score, condition_score, investment_score, overall_score, latitude, longitude, top_rated, ready_status, is_sold, price_max, land_type, land_features, payment_method, down_payment_percent, installment_duration, best_price, title_en, description_en, acceptable_price, high_price, live_enabled, live_title, live_embed_url, live_source_type, live_status, live_thumbnail, live_country, live_city, live_updated_at, monthly_installment, remaining_balance, payment_notes) VALUES (6, 'Sky Blade', 'PROJECT HIGHLIGHTS – BINGHATTI SKYBLADE
Prime location in Downtown Dubai, close to Burj Khalifa and Dubai Mall

Collection of 621 residences across studios, suites, and Burj-facing wings

Premium studios with Jacuzzi and 1-bedroom Royal Suites with lap pools

2-bedroom Burj Royal Suites on top floors with direct Burj Khalifa views

